import { drizzle } from "drizzle-orm/node-postgres";
import { Client } from "pg";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { schema } from "@/lib/db/schema";

const databaseUrl = process.env.DATABASE_URL;
const describeDatabase = databaseUrl ? describe : describe.skip;

describeDatabase("sighting persistence", () => {
  let client: Client;

  beforeEach(async () => {
    client = new Client({ connectionString: databaseUrl });
    await client.connect();
    await client.query('DROP TABLE IF EXISTS "sightings"');

    const migration = await readFile(
      new URL(
        "../../drizzle/20260811072733_early_luke_cage/migration.sql",
        import.meta.url
      ),
      "utf8"
    );
    for (const statement of migration.split("--> statement-breakpoint")) {
      await client.query(statement);
    }
  });

  afterEach(async () => {
    await client.end();
  });

  it("applies the baseline constraints and permits duplicate label facts", async () => {
    if (!databaseUrl) {
      return;
    }

    const database = drizzle(databaseUrl, { schema });
    const { createSightingOperations } = await import("./sightings.server");
    const operations = createSightingOperations(database);

    try {
      const first = await operations.create({
        labelDate: "2026-08-11",
        labelMinute: 845,
      });
      const duplicate = await operations.create({
        labelDate: "2026-08-11",
        labelMinute: 845,
      });

      expect(first).toMatchObject({
        ok: true,
        sighting: { doneness: null, labelDate: "2026-08-11", labelMinute: 845 },
      });
      expect(duplicate).toMatchObject({
        ok: true,
        sighting: { labelDate: "2026-08-11", labelMinute: 845 },
      });
      expect(first.ok && duplicate.ok && duplicate.sighting.id).toBeGreaterThan(
        first.ok ? first.sighting.id : 0
      );

      await expect(
        client.query(
          "insert into sightings (label_date, label_minute) values ('2026-08-11', 1440)"
        )
      ).rejects.toMatchObject({ code: "23514" });
      await expect(
        client.query(
          "insert into sightings (label_date, label_minute, doneness) values ('2026-08-11', 0, 'raw')"
        )
      ).rejects.toMatchObject({ code: "23514" });
    } finally {
      await database.$client.end();
    }
  });

  it("creates the required representation and only its initial recency index", async () => {
    const columns = await client.query<{ column_name: string }>(
      "select column_name from information_schema.columns where table_name = 'sightings' order by ordinal_position"
    );
    const indexes = await client.query<{ indexname: string }>(
      "select indexname from pg_indexes where tablename = 'sightings' order by indexname"
    );

    expect(columns.rows.map((column) => column.column_name)).toEqual([
      "id",
      "label_date",
      "label_minute",
      "doneness",
      "created_at",
      "updated_at",
    ]);
    expect(indexes.rows.map((index) => index.indexname)).toEqual([
      "sightings_pkey",
      "sightings_recent_idx",
    ]);
  });
});
import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { saveSighting } from "@/lib/sighting-functions";
import {
  type CreateSighting,
  type CreateSightingInput,
  createSightingInputSchema,
  type Sighting,
} from "@/lib/sightings";

export const Route = createFileRoute("/")({
  component: CapturePage,
});

interface LabelTime {
  labelDate: string;
  labelTime: string;
}

const getCurrentDeviceTime = (): Date => new Date();
const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

function padTimePart(value: number): string {
  return value.toString().padStart(2, "0");
}

export function getDeviceLabelTime(date: Date): LabelTime {
  return {
    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
  };
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = LABEL_TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function isOutsideStoreHours(labelMinute: number | undefined): boolean {
  return (
    labelMinute !== undefined && (labelMinute < 9 * 60 || labelMinute > 20 * 60)
  );
}

function formatSavedLabelTime(sighting: Sighting): string {
  const date = new Date(`${sighting.labelDate}T12:00:00`);
  const hour = Math.floor(sighting.labelMinute / 60);
  const minute = sighting.labelMinute % 60;
  const time = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(2000, 0, 1, hour, minute));
  const formattedDate = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(date);

  return `Saved label time for ${formattedDate} at ${time}.`;
}

export function CapturePage() {
  const save = useServerFn(saveSighting);
  const saveSightingFromRoute: CreateSighting = async (input) =>
    save({ data: input });

  return <CaptureForm saveSighting={saveSightingFromRoute} />;
}

export function CaptureForm({
  now = getCurrentDeviceTime,
  saveSighting,
}: Readonly<{
  now?: () => Date;
  saveSighting: CreateSighting;
}>) {
  const [labelTime, setLabelTime] = useState<LabelTime>(() =>
    getDeviceLabelTime(now())
  );
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isSaving, setIsSaving] = useState(false);
  const [savedSighting, setSavedSighting] = useState<Sighting>();

  useEffect(() => {
    setLabelTime(getDeviceLabelTime(now()));
  }, [now]);

  const labelMinute = labelTimeToMinute(labelTime.labelTime);
  const outsideStoreHours = isOutsideStoreHours(labelMinute);

  const handleSave = async (): Promise<void> => {
    if (isSaving) {
      return;
    }

    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const input: CreateSightingInput = {
      labelDate: labelTime.labelDate,
      labelMinute,
    };
    const validation = createSightingInputSchema.safeParse(input);
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    const result = await saveSighting(validation.data);
    setIsSaving(false);

    if (!result.ok) {
      setErrorMessage(result.message);
      return;
    }

    setSavedSighting(result.sighting);
  };

  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Capture</h1>
        <p className="mt-2 text-muted-foreground">
          Record the label time exactly as printed.
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Label time</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-6">
            <div className="grid gap-2">
              <Label htmlFor="label-time">Label time</Label>
              <Input
                aria-describedby={
                  outsideStoreHours ? "store-hours-warning" : undefined
                }
                className="h-16 text-3xl"
                id="label-time"
                onChange={(event) => {
                  setLabelTime((current) => ({
                    ...current,
                    labelTime: event.target.value,
                  }));
                }}
                required
                type="time"
                value={labelTime.labelTime}
              />
              {outsideStoreHours ? (
                <p
                  className="text-sm text-warning-foreground"
                  id="store-hours-warning"
                >
                  Outside store hours
                </p>
              ) : null}
            </div>
            <div className="grid gap-2">
              <Label htmlFor="label-date">Label date</Label>
              <Input
                id="label-date"
                onChange={(event) => {
                  setLabelTime((current) => ({
                    ...current,
                    labelDate: event.target.value,
                  }));
                }}
                required
                type="date"
                value={labelTime.labelDate}
              />
            </div>
            {errorMessage ? (
              <p
                aria-live="assertive"
                className="text-destructive text-sm"
                role="alert"
              >
                {errorMessage}
              </p>
            ) : null}
            {isSaving ? (
              <output aria-live="polite">Saving label time…</output>
            ) : null}
            {savedSighting ? (
              <output aria-live="polite" className="text-success-foreground">
                {formatSavedLabelTime(savedSighting)}
              </output>
            ) : null}
            <Button
              className="h-12 text-base"
              disabled={isSaving}
              onClick={handleSave}
              type="button"
            >
              Save label time
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
